PyObject *
PyContextAttributes_getattro(PyObject *self, PyObject *attr_name)
{
    const char *name = PyUnicode_AsUTF8(attr_name);
    if (!name) return NULL;

    if(strcmp(name, "offset") == 0)
        return ContextAttributes_GetOffset(self, NULL);
    if(strcmp(name, "low") == 0)
        return ContextAttributes_GetLow(self, NULL);
    if(strcmp(name, "hi") == 0)
        return ContextAttributes_GetHi(self, NULL);
    if(strcmp(name, "context") == 0)
        return ContextAttributes_GetContext(self, NULL);
    if(strcmp(name, "cutoff") == 0)
        return ContextAttributes_GetCutoff(self, NULL);
    if(strcmp(name, "below") == 0)
        return ContextAttributes_GetBelow(self, NULL);
    if(strcmp(name, "above") == 0)
        return ContextAttributes_GetAbove(self, NULL);

    PyObject *meth = Py_FindMethod(PyContextAttributes_methods, self, (char*)name);
    if (meth) return meth;

    return PyObject_GenericGetAttr(self, attr_name);
}

int
PyContextAttributes_setattro(PyObject *self, PyObject *attr_name, PyObject *args)
{
    PyObject NULL_PY_OBJ;
    PyObject *obj = &NULL_PY_OBJ;
    const char *name = PyUnicode_AsUTF8(attr_name);
    if (!name) return -1;

    if(strcmp(name, "offset") == 0)
        obj = ContextAttributes_SetOffset(self, args);
    else if(strcmp(name, "low") == 0)
        obj = ContextAttributes_SetLow(self, args);
    else if(strcmp(name, "hi") == 0)
        obj = ContextAttributes_SetHi(self, args);
    else if(strcmp(name, "context") == 0)
        obj = ContextAttributes_SetContext(self, args);
    else if(strcmp(name, "cutoff") == 0)
        obj = ContextAttributes_SetCutoff(self, args);
    else if(strcmp(name, "below") == 0)
        obj = ContextAttributes_SetBelow(self, args);
    else if(strcmp(name, "above") == 0)
        obj = ContextAttributes_SetAbove(self, args);

    if (obj == &NULL_PY_OBJ && PyObject_GenericSetAttr(self, attr_name, args) == 0)
    {
        Py_INCREF(Py_None);
        obj = Py_None;
    }

    if (obj != NULL && obj != &NULL_PY_OBJ)
        Py_DECREF(obj);

    if (obj == &NULL_PY_OBJ)
    {
        obj = NULL;
        PyErr_Format(PyExc_NameError, "name '%s' is not defined", name);
    }
    else if (obj == NULL && !PyErr_Occurred())
        PyErr_Format(PyExc_RuntimeError, "unknown problem with '%s'", name);

    return (obj != NULL) ? 0 : -1;
}

